mapper.select:

select m.*,
       i.instrument_name as instrumentName,
       i.instrument_no as instrumentNo,
       u.real_name as operatorUserName
from biz_maintenance_record m
inner join biz_instrument i on i.id = m.instrument_id and i.deleted = 0
left join sys_user u on u.id = m.operator_user_id
where 1 = 1

  and m.instrument_id = #{instrumentId}


  and m.status = #{status}


  and i.owner_user_id = #{operatorId}


  and i.department_id = #{departmentId}

order by m.start_time desc, m.id desc
limit #{offset}, #{pageSize}

select count(1)
from biz_maintenance_record m
inner join biz_instrument i on i.id = m.instrument_id and i.deleted = 0
where 1 = 1

  and m.instrument_id = #{instrumentId}


  and m.status = #{status}


  and i.owner_user_id = #{operatorId}


  and i.department_id = #{departmentId}

mapper.insert:
insert into biz_maintenance_record(
  instrument_id, maint_type, title, content, start_time, end_time, operator_user_id, status, create_time, update_time
) values (
  #{instrumentId}, #{maintType}, #{title}, #{content}, #{startTime}, #{endTime}, #{operatorUserId}, #{status}, #{createTime}, #{updateTime}
)
